class Solution {
public:
    string strWithout3a3b(int a, int b) {
        string res = "";
        while (a > 0 || b > 0) {
            int n = res.size();
            if (n >= 2 && res[n - 1] == 'a' && res[n - 2] == 'a') {
                res.push_back('b');
                b--;
            } else if (n >= 2 && res[n - 1] == 'b' && res[n - 2] == 'b') {
                res.push_back('a');
                a--;
            } else if (a >= b) {
                res.push_back('a');
                a--;
            } else {
                res.push_back('b');
                b--;
            }
        }
        return res;
    }
};

class Solution {
    public String strWithout3a3b(int a, int b) {
        StringBuilder sb = new StringBuilder();
        while (a > 0 || b > 0) {
            int n = sb.length();
            if (n >= 2 && sb.charAt(n - 1) == 'a' && sb.charAt(n - 2) == 'a') {
                sb.append('b');
                b--;
            } else if (n >= 2 && sb.charAt(n - 1) == 'b' && sb.charAt(n - 2) == 'b') {
                sb.append('a');
                a--;
            } else if (a >= b) {
                sb.append('a');
                a--;
            } else {
                sb.append('b');
                b--;
            }
        }
        return sb.toString();
    }
}

